{
  "itinerary": {
    "destination": "Moscow, Russia",
    "duration": "3 days",
    "days": [
      {
        "day": 1,
        "activities": [
          "Arrive at Tverskaya Station and check into a hotel near the Red Square.",
          "Visit the State Historical Museum to see the Tretyakov Gallery.",
          "Take a walk along the Bolshoi Island promenade.",
          "Dinner at a traditional Russian bistro in the Kremlin district."
        ]
      },
      {
        "day": 2,
        "activities": [
          "Morning: Explore the Winter Palace and the State Kremlin Museum.",
          "Afternoon: Visit the Hermitage Museum and the Peter and Paul Cathedral.",
          "Evening: Experience a traditional Russian dinner with a live folk music performance.",
          "Late night: Stroll through the illuminated streets of the Red Square."
        ]
      },
      {
        "day": 3,
        "activities": [
          "Morning: Visit the Moscow Kremlin Wall Fortress and the Peterhof Palace.",
          "Afternoon: Explore the Moscow State University and the National Museum of Russian Literature.",
          "Evening: Enjoy a farewell dinner at a famous Moscow restaurant like 'Kutuzov' or 'Kuznetsov'."
        ]
      }
    ]
  }
}
